import{_ as t,c as a,o as n,ag as i}from"./chunks/framework.CoPVQkzc.js";const p=JSON.parse('{"title":"Contributing to Open Integration Engine","description":"","frontmatter":{},"headers":[],"relativePath":"engine/contributing.md","filePath":"engine/contributing.md","lastUpdated":1765688656000}'),r={name:"engine/contributing.md"};function o(s,e,l,h,u,c){return n(),a("div",null,e[0]||(e[0]=[i('<h1 id="contributing-to-open-integration-engine" tabindex="-1">Contributing to Open Integration Engine <a class="header-anchor" href="#contributing-to-open-integration-engine" aria-label="Permalink to &quot;Contributing to Open Integration Engine&quot;">​</a></h1><p>Thank you for your interest in contributing to the <strong>Open Integration Engine</strong> project. Contributions are vital to the continued growth and success of the project, and we welcome all forms of participation, whether you are a developer, a documentation contributor, or a user providing feedback.</p><p>The contribution process is straightforward and can be completed in a few simple steps:</p><h2 id="how-to-contribute" tabindex="-1">How to Contribute <a class="header-anchor" href="#how-to-contribute" aria-label="Permalink to &quot;How to Contribute&quot;">​</a></h2><h3 id="_1-open-an-issue" tabindex="-1">1. Open an Issue <a class="header-anchor" href="#_1-open-an-issue" aria-label="Permalink to &quot;1. Open an Issue&quot;">​</a></h3><p>Before making any changes, please open an issue in the <a href="https://github.com/OpenIntegrationEngine/engine/issues" target="_blank" rel="noreferrer">GitHub Issues Tracker</a>. This step helps us discuss the problem or feature before work begins, ensuring alignment and reducing redundant efforts.</p><h3 id="_2-fork-the-repository" tabindex="-1">2. Fork the Repository <a class="header-anchor" href="#_2-fork-the-repository" aria-label="Permalink to &quot;2. Fork the Repository&quot;">​</a></h3><p>Start by forking the <a href="https://github.com/OpenIntegrationEngine/engine" target="_blank" rel="noreferrer">Open Integration Engine GitHub repository</a> to your own GitHub account.</p><h3 id="_3-clone-your-fork" tabindex="-1">3. Clone Your Fork <a class="header-anchor" href="#_3-clone-your-fork" aria-label="Permalink to &quot;3. Clone Your Fork&quot;">​</a></h3><p>Clone your fork locally to your development environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:your-github/engine.git</span></span></code></pre></div><h3 id="_4-make-changes" tabindex="-1">4. Make Changes <a class="header-anchor" href="#_4-make-changes" aria-label="Permalink to &quot;4. Make Changes&quot;">​</a></h3><p>Create a new branch for your feature or bug fix:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/your-feature-name</span></span></code></pre></div><h3 id="_5-install-tooling" tabindex="-1">5. Install Tooling <a class="header-anchor" href="#_5-install-tooling" aria-label="Permalink to &quot;5. Install Tooling&quot;">​</a></h3><p>OIE specifies the working versions of Java and Ant in <a href="https://github.com/OpenIntegrationEngine/engine/blob/main/.sdkmanrc" target="_blank" rel="noreferrer"><code>.sdkmanrc</code></a>. To take advantage of this, install <a href="https://sdkman.io/" target="_blank" rel="noreferrer">SDKMAN</a> and run <code>sdk env install</code> in the project&#39;s root directory.</p><h3 id="_6-implement-your-changes" tabindex="-1">6. Implement your changes <a class="header-anchor" href="#_6-implement-your-changes" aria-label="Permalink to &quot;6. Implement your changes&quot;">​</a></h3><p>Implement the necessary changes, ensuring they align with the project’s coding standards and practices.</p><h3 id="_7-test-your-changes" tabindex="-1">7. Test Your Changes <a class="header-anchor" href="#_7-test-your-changes" aria-label="Permalink to &quot;7. Test Your Changes&quot;">​</a></h3><p>Before submitting your changes, please ensure that all tests pass and that your changes work as expected in your local environment.</p><h3 id="_8-submit-a-pull-request" tabindex="-1">8. Submit a Pull Request <a class="header-anchor" href="#_8-submit-a-pull-request" aria-label="Permalink to &quot;8. Submit a Pull Request&quot;">​</a></h3><p>Once your changes are ready, push them to your fork and create a <strong>draft pull request (PR)</strong> from your branch to the <code>main</code> branch of the project. Draft PRs help indicate that the work is in progress. Mark the PR as <strong>&quot;Ready for review&quot;</strong> only when it is actually complete and ready for feedback. Include a brief description of the changes and reference the related issue.</p><h2 id="reporting-bugs" tabindex="-1">Reporting Bugs <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;Reporting Bugs&quot;">​</a></h2><p>If you encounter a bug, please report it using the <strong>GitHub Issues Tracker</strong>:</p><ol><li><strong>Search for existing issues</strong> to check if the problem has already been reported.</li><li>If the issue is not listed, create a new issue with the following information: <ul><li>A clear and descriptive title.</li><li>Steps to reproduce the issue.</li><li>The expected vs. actual behavior.</li><li>Any relevant logs, error messages, or screenshots to help diagnose the issue.</li></ul></li></ol><h2 id="suggesting-features" tabindex="-1">Suggesting Features <a class="header-anchor" href="#suggesting-features" aria-label="Permalink to &quot;Suggesting Features&quot;">​</a></h2><p>If you would like to suggest a new feature or enhancement:</p><ol><li>Open a new issue in the <strong>GitHub Issues Tracker</strong>.</li><li>Label the issue as a <strong>feature request</strong>.</li><li>Provide a detailed description of the feature and the problem it aims to solve.</li><li>If applicable, include examples or use cases to demonstrate the value of the feature.</li></ol><h2 id="community-guidelines" tabindex="-1">Community Guidelines <a class="header-anchor" href="#community-guidelines" aria-label="Permalink to &quot;Community Guidelines&quot;">​</a></h2><ul><li>Be respectful and professional in all interactions.</li><li>Provide constructive feedback and suggestions.</li><li>Engage in discussions around pull requests and issues with an open and collaborative mindset.</li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>By contributing to <strong>Open Integration Engine</strong>, you agree that your contributions will be licensed under the <a href="https://github.com/OpenIntegrationEngine/engine/blob/main/LICENSE" target="_blank" rel="noreferrer">Mozilla Public License (MPL) 2.0</a>.</p><p>Thank you for your interest in improving <strong>Open Integration Engine</strong>.</p>',33)]))}const d=t(r,[["render",o]]);export{p as __pageData,d as default};
